import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

// SKOR 보상 티어 (난이도별, 순위별)
const SEASON_REWARD_TIERS = {
  normal:   [{ maxRank: 1, skor: 500  }, { maxRank: 3, skor: 300  }, { maxRank: 10, skor: 150 }, { maxRank: 30, skor: 80 }, { maxRank: 100, skor: 30 }],
  hard:     [{ maxRank: 1, skor: 800  }, { maxRank: 3, skor: 500  }, { maxRank: 10, skor: 200 }, { maxRank: 30, skor: 100}, { maxRank: 100, skor: 50 }],
  extreme:  [{ maxRank: 1, skor: 1500 }, { maxRank: 3, skor: 900  }, { maxRank: 10, skor: 350 }, { maxRank: 30, skor: 150}, { maxRank: 100, skor: 70 }],
  physical: [{ maxRank: 1, skor: 2000 }, { maxRank: 3, skor: 1200 }, { maxRank: 10, skor: 500 }, { maxRank: 30, skor: 200}, { maxRank: 100, skor: 90 }],
} as const;

type RewardDifficulty = keyof typeof SEASON_REWARD_TIERS;

function getReward(difficulty: RewardDifficulty, rank: number): number {
  const tiers = SEASON_REWARD_TIERS[difficulty];
  for (const tier of tiers) {
    if (rank <= tier.maxRank) return tier.skor;
  }
  return 0;
}

/** 현재 달 'YYYY-MM' 반환 (UTC 기준) */
function getCurrentYearMonth(): string {
  const now = new Date();
  const y = now.getUTCFullYear();
  const m = String(now.getUTCMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

/** 직전 달 'YYYY-MM' 반환 */
function getPrevYearMonth(current: string): string {
  const [y, m] = current.split('-').map(Number) as [number, number];
  const prev = new Date(Date.UTC(y, m - 2, 1));
  return `${prev.getUTCFullYear()}-${String(prev.getUTCMonth() + 1).padStart(2, '0')}`;
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
