      const rawAbilityBonus = verification?.abilityBonusTotal ?? 0;
      const abilityBonusTotal = Math.min(rawAbilityBonus, score * ABILITY_BONUS_CAP_RATIO);
      if (rawAbilityBonus > abilityBonusTotal) {
