      }
      const bonusScore =
        (verification?.goldCollected ?? 0) * 20 +
        (verification?.diamondCollected ?? 0) * 40 +
        (verification?.topazCollected ?? 0) * 80 +
        (verification?.rainbowCollected ?? 0) * 90 +
