/** 보상수령 버튼 상태 갱신 */
private updateRewardUI() {
  if (!this.rewardBtnBg || !this.rewardBtnLabel || !this.rewardBtnSub) return;

  const btn = this.rewardBtnBg;
  const label = this.rewardBtnLabel;
  const sub = this.rewardBtnSub;
  const reward = this.prevSeasonReward;

  // 이벤트 초기화
  btn.removeAllListeners();
  btn.disableInteractive();

  if (!reward || reward.rank === null) {
    // 비활성: 기록 없음
    btn.setFillStyle(0x555555).setStrokeStyle(2, 0x333333);
    label.setText('보상수령').setColor('#999999');
    sub.setText('기록없음').setColor('#777777');

  } else if (reward.skorAwarded === 0) {
    // 비활성: 100위 밖
    btn.setFillStyle(0x555555).setStrokeStyle(2, 0x333333);
    label.setText('보상수령').setColor('#999999');
    sub.setText(`${reward.rank}위 밖`).setColor('#777777');

  } else if (reward.alreadyClaimed) {
    // 비활성: 수령 완료
    btn.setFillStyle(0x336633).setStrokeStyle(2, 0x224422);
    label.setText('수령완료').setColor('#88ff88');
    sub.setText(`+${reward.skorAwarded}`).setColor('#66cc66');

  } else {
    // 활성: 수령 가능
    btn.setFillStyle(0xffcc00).setStrokeStyle(2, 0xaa8800);
    label.setText('보상수령').setColor('#000000');
    sub.setText(`+${reward.skorAwarded}`).setColor('#333300');
    btn.setInteractive({ useHandCursor: true });
    btn.on('pointerover', () => btn.setFillStyle(0xffe566));
    btn.on('pointerout', () => btn.setFillStyle(0xffcc00));
    btn.on('pointerdown', () => this.handleClaimReward());
  }
}

