import type Phaser from 'phaser';
import { Difficulty, Difficulty as DifficultyEnum } from '../types/GameMode';
import {
  getLeaderboard,
  claimSeasonReward,
  getCachedClaimAmount,
  type LeaderboardEntry,
  type PrevSeasonReward,
} from '../utils/leaderboard';
import BaseScene from './BaseScene';

export default class LeaderboardScene extends BaseScene {
  private selectedDifficulty: Difficulty = DifficultyEnum.NORMAL;
  private leaderboardData: LeaderboardEntry[] = [];
  private leaderboardTexts: Phaser.GameObjects.Text[] = [];
  private loadingText?: Phaser.GameObjects.Text;
  private errorText?: Phaser.GameObjects.Text;
  private currentRequestId: number = 0;
  private difficultyButtons = new Map<Difficulty, Phaser.GameObjects.Rectangle>();

  // 시즌 UI 요소
  private seasonText?: Phaser.GameObjects.Text;
  private rewardAreaObjects: Phaser.GameObjects.GameObject[] = [];
  private prevSeasonReward: PrevSeasonReward | null = null;

  // 보상수령 버튼 (create에서 1회 생성, updateRewardUI에서 상태 변경)
  private rewardBtnBg?: Phaser.GameObjects.Rectangle;
  private rewardBtnLabel?: Phaser.GameObjects.Text;
  private rewardBtnSub?: Phaser.GameObjects.Text;

  constructor() {
    super('LeaderboardScene');
  }

  init() {
    const last = localStorage.getItem('lastPlayedDifficulty') as Difficulty | null;
    if (last) {
      this.selectedDifficulty = last;
    }
  }

  preload() {
    // 배경 이미지 로드 (캐시 확인으로 중복 로딩 방지)
    if (!this.textures.exists('background2')) {
      this.load.image('background2', 'assets/backgrounds/background2.webp');
    }
  }

  create() {
    super.create();

    const W = this.scale.width;
    const H = this.scale.height;
    const cx = W / 2;
    const yOff = (H - 600) / 2;

    // 배경 이미지 추가
    const background = this.add.image(cx, H / 2, 'background2');
    background.setDisplaySize(W, H);

    // 타이틀
    this.add.text(cx, 40 + yOff, '🏆 랭킹보드 🏆', {
      fontSize: '28px',
      color: '#fff',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 5,
      padding: { top: 6 },
    }).setOrigin(0.5);

    // 보상수령 버튼 (오른쪽 상단 고정, 상태는 updateRewardUI에서 변경)
    const btnX = W - 46;
    const btnY = 63 + yOff;
    this.rewardBtnBg = this.add.rectangle(btnX, btnY, 76, 46, 0x555555, 1);
    this.rewardBtnBg.setStrokeStyle(2, 0x333333);
    this.rewardBtnLabel = this.add.text(btnX, btnY - 7, '보상수령', {
      fontSize: '12px',
      color: '#999999',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);
    this.rewardBtnSub = this.add.text(btnX, btnY + 9, '기록없음', {
      fontSize: '10px',
      color: '#777777',
      stroke: '#000',
      strokeThickness: 2,
    }).setOrigin(0.5);

    // 시즌 월 표시 (데이터 로드 후 갱신)
    this.seasonText = this.add.text(cx - 38, 70 + yOff, '', {
      fontSize: '13px',
      color: '#aaddff',
      stroke: '#000',
      strokeThickness: 3,
    }).setOrigin(0.5);

    // 난이도 선택 버튼들
    this.createDifficultyButtons(cx, yOff);

    // 랭킹 표시 영역 (초기 로딩)
    this.loadingText = this.add.text(cx, H / 2, '로딩 중...', {
      fontSize: '20px',
      color: '#fff',
      stroke: '#000',
      strokeThickness: 3
    }).setOrigin(0.5);

    // 뒤로가기 버튼
    this.createBackButton(cx, H - 40);

    // 초기 데이터 로드
    this.loadLeaderboard();
  }

  private createDifficultyButtons(cx: number, yOff: number) {
    this.difficultyButtons.forEach(btn => btn.destroy());
    this.difficultyButtons.clear();

    const difficulties: Difficulty[] = [
      DifficultyEnum.NORMAL,
      DifficultyEnum.HARD,
      DifficultyEnum.EXTREME,
      DifficultyEnum.PHYSICAL
    ];

    const buttonWidth = 70;
    const spacing = 85;
    const startX = cx - (spacing * 1.5);
    const y = 108 + yOff;

    difficulties.forEach((difficulty, index) => {
      const x = startX + (index * spacing);
      const isSelected = difficulty === this.selectedDifficulty;

      const button = this.add.rectangle(
        x,
        y,
        buttonWidth,
        35,
        isSelected ? 0xffff99 : 0xffffff,
        1
      );
      button.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);

      this.add.text(x, y, difficulty, {
        fontSize: '12px',
        color: '#000',
        fontStyle: 'bold'
      }).setOrigin(0.5);

      this.difficultyButtons.set(difficulty, button);
      button.setInteractive({ useHandCursor: true });

      button.on('pointerover', () => {
        if (difficulty !== this.selectedDifficulty) {
          button.setFillStyle(0xffffcc);
        }
      });

      button.on('pointerout', () => {
        if (difficulty !== this.selectedDifficulty) {
          button.setFillStyle(0xffffff);
        }
      });

      button.on('pointerdown', () => {
        this.selectDifficulty(difficulty);
      });
    });
  }

  private selectDifficulty(difficulty: Difficulty) {
    // 같은 난이도면 무시
    if (this.selectedDifficulty === difficulty) {
      return;
    }

    this.selectedDifficulty = difficulty;

    // 모든 버튼 스타일 재설정
    this.difficultyButtons.forEach((btn, diff) => {
      const isSelected = diff === difficulty;
      btn.setFillStyle(isSelected ? 0xffff99 : 0xffffff);
      btn.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
    });

    // 새로운 난이도 데이터 로드
    this.loadLeaderboard();
  }

  private async loadLeaderboard() {
    // 요청 ID 증가 (새로운 요청 시작)
    this.currentRequestId++;
    const requestId = this.currentRequestId;

    // 기존 랭킹 텍스트 + 보상 UI 제거
    this.leaderboardTexts.forEach(text => text.destroy());
    this.leaderboardTexts = [];
    this.rewardAreaObjects.forEach(o => o.destroy());
    this.rewardAreaObjects = [];
    this.prevSeasonReward = null;

    if (this.errorText) {
      this.errorText.destroy();
      this.errorText = undefined;
    }

    // 로딩 표시
    if (!this.loadingText) {
      this.loadingText = this.add.text(this.scale.width / 2, this.scale.height / 2, '로딩 중...', {
        fontSize: '20px',
        color: '#fff',
        stroke: '#000',
        strokeThickness: 3
      }).setOrigin(0.5);
    } else {
      this.loadingText.setVisible(true);
    }

    try {
      const response = await getLeaderboard(this.selectedDifficulty, 10);

      // 응답이 도착했을 때 최신 요청인지 확인
      if (requestId !== this.currentRequestId) {
        // 이미 새로운 요청이 시작됨 - 이 응답은 무시
        return;
      }

      this.leaderboardData = response.leaderboard;

      // 시즌 텍스트 갱신
      if (this.seasonText && response.yearMonth) {
        const [y, m] = response.yearMonth.split('-');
        const daysLeft = this.calcDaysUntilMonthEnd();
        this.seasonText.setText(`${y}년 ${parseInt(m)}월 시즌  |  시즌 종료까지 D-${daysLeft}`);
      }

      // 직전 달 보상 상태 결정 (localStorage 캐시 우선)
      const rewardDiffs: Difficulty[] = [DifficultyEnum.NORMAL, DifficultyEnum.HARD, DifficultyEnum.EXTREME, DifficultyEnum.PHYSICAL];
      if (rewardDiffs.includes(this.selectedDifficulty) && response.yearMonth) {
        const [y, m] = response.yearMonth.split('-').map(Number) as [number, number];
        const prevDate = new Date(y, m - 2, 1);
        const prevYM = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
        const cached = getCachedClaimAmount(prevYM, this.selectedDifficulty);
        if (cached !== null) {
          // localStorage 캐시 히트 → 서버 응답의 prevSeasonReward 무시하고 캐시 사용
          this.prevSeasonReward = {
            yearMonth: prevYM,
            rank: response.prevSeasonReward?.rank ?? null,
            skorAwarded: cached,
            alreadyClaimed: true,
          };
        } else {
          this.prevSeasonReward = response.prevSeasonReward;
        }
      } else {
        this.prevSeasonReward = null;
      }

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.displayLeaderboard();
      this.updateRewardUI();
    } catch (error) {
      // 에러가 발생했을 때도 최신 요청인지 확인
      if (requestId !== this.currentRequestId) {
        // 이미 새로운 요청이 시작됨 - 이 에러는 무시
        return;
      }

      console.error('Failed to load leaderboard:', error);

      if (this.loadingText) {
        this.loadingText.setVisible(false);
      }

      this.errorText = this.add.text(this.scale.width / 2, this.scale.height / 2, '랭킹을 불러올 수 없습니다\n\n나중에 다시 시도해주세요', {
        fontSize: '16px',
        color: '#ff6666',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center'
      }).setOrigin(0.5);
    }
  }

  private displayLeaderboard() {
    const yOff = (this.scale.height - 600) / 2;
    const cx = this.scale.width / 2;
    const startY = 163 + yOff;
    const lineHeight = 35;

    // 헤더
    const headerText = this.add.text(cx, startY, '순위    이름      점수', {
      fontSize: '16px',
      color: '#ffff00',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 4
    }).setOrigin(0.5);
    this.leaderboardTexts.push(headerText);

    // 랭킹 데이터 표시
    if (this.leaderboardData.length === 0) {
      const noDataText = this.add.text(cx, startY + 50, '아직 랭킹이 없습니다\n\n첫 번째 플레이어가 되어보세요!', {
        fontSize: '18px',
        color: '#ccc',
        stroke: '#000',
        strokeThickness: 3,
        align: 'center'
      }).setOrigin(0.5);
      this.leaderboardTexts.push(noDataText);
      return;
    }

    this.leaderboardData.forEach((entry, index) => {
      const y = startY + 30 + (index * lineHeight);

      // 순위별 색상
      let color = '#ffffff';
      if (entry.rank === 1) color = '#FFD700'; // 금색
      else if (entry.rank === 2) color = '#C0C0C0'; // 은색
      else if (entry.rank === 3) color = '#CD7F32'; // 동색


      const rankText = `${entry.rank}`.padEnd(8, ' ');
      const nameText = entry.userName.padEnd(8, ' ');
      const scoreText = entry.score.toString().padStart(6, ' ');

      const text = this.add.text(
        cx,
        y,
        `${rankText}${nameText}${scoreText}`,
        {
          fontSize: '16px',
          color: color,
          fontFamily: 'monospace',
          stroke: '#000',
          strokeThickness: 3
        }
      ).setOrigin(0.5);

      this.leaderboardTexts.push(text);
    });
  }

  /** 이번 달 말일까지 남은 일수 */
  private calcDaysUntilMonthEnd(): number {
    const now = new Date();
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    const diff = lastDay.getTime() - now.getTime();
    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
  }

  /** 직전 달 'YYYY년 M월' 포맷 */
  private formatPrevSeasonLabel(yearMonth: string): string {
    const [y, m] = yearMonth.split('-');
    return `${y}년 ${parseInt(m)}월`;
  }

  /** 보상 영역 UI 갱신 (탭 전환 또는 데이터 로드 시 호출) */
  private updateRewardUI() {
    // 기존 보상 UI 제거
    this.rewardAreaObjects.forEach(o => o.destroy());
    this.rewardAreaObjects = [];

    const reward = this.prevSeasonReward;
    const H = this.scale.height;
    const cx = this.scale.width / 2;
    const areaY = H - 95;

    // 직전 달 레이블 계산 (prevSeasonReward가 없어도 표시용으로 사용)
    const now = new Date();
    const prevDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const prevYM = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
    const prevLabel = this.formatPrevSeasonLabel(reward?.yearMonth ?? prevYM);
    const diffLabel = this.selectedDifficulty.toUpperCase();

    // 구분선
    const divText = this.add.text(cx, areaY - 16, `─── 지난 시즌 (${prevLabel}) ${diffLabel} ───`, {
      fontSize: '11px',
      color: '#aaaaaa',
      stroke: '#000',
      strokeThickness: 2,
    }).setOrigin(0.5);
    this.rewardAreaObjects.push(divText);

    // 상태별 분기
    if (!reward || reward.rank === null) {
      // 직전 달 기록 없음
      const noDataText = this.add.text(cx, areaY + 14, '지난 시즌 기록이 없습니다', {
        fontSize: '14px',
        color: '#888888',
        stroke: '#000',
        strokeThickness: 3,
      }).setOrigin(0.5);
      this.rewardAreaObjects.push(noDataText);
    } else if (reward.skorAwarded === 0) {
      // 100위 밖
      const outText = this.add.text(cx, areaY + 14, `${reward.rank}위  ·  보상 대상 순위 밖`, {
        fontSize: '14px',
        color: '#888888',
        stroke: '#000',
        strokeThickness: 3,
      }).setOrigin(0.5);
      this.rewardAreaObjects.push(outText);
    } else if (reward.alreadyClaimed) {
      // 수령 완료
      const doneText = this.add.text(cx, areaY + 14, `✅  보상 수령 완료  +${reward.skorAwarded} SKOR`, {
        fontSize: '15px',
        color: '#88ff88',
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 4,
      }).setOrigin(0.5);
      this.rewardAreaObjects.push(doneText);
    } else {
      // 수령 가능 버튼
      const btnBg = this.add.rectangle(cx, areaY + 14, 240, 36, 0xffcc00, 1);
      btnBg.setStrokeStyle(3, 0xaa8800);
      btnBg.setInteractive({ useHandCursor: true });

      const btnText = this.add.text(cx, areaY + 14,
        `🏆  ${reward.rank}위 보상받기  +${reward.skorAwarded} SKOR`, {
        fontSize: '14px',
        color: '#000',
        fontStyle: 'bold',
      }).setOrigin(0.5);

      btnBg.on('pointerover', () => btnBg.setFillStyle(0xffe566));
      btnBg.on('pointerout', () => btnBg.setFillStyle(0xffcc00));
      btnBg.on('pointerdown', () => this.handleClaimReward(btnBg, btnText));

      this.rewardAreaObjects.push(btnBg, btnText);
    }
  }

  /** 보상받기 버튼 클릭 처리 */
  private async handleClaimReward(
    btnBg: Phaser.GameObjects.Rectangle,
    btnText: Phaser.GameObjects.Text
  ) {
    // 버튼 비활성화 (중복 클릭 방지)
    btnBg.disableInteractive();
    btnText.setText('처리 중...');

    try {
      const result = await claimSeasonReward(this.selectedDifficulty);

      if (result.success && (result.skorAwarded ?? 0) > 0) {
        // 수령 완료 → UI 갱신
        if (this.prevSeasonReward) {
          this.prevSeasonReward = { ...this.prevSeasonReward, alreadyClaimed: true };
        }
        this.updateRewardUI();

        // 간단한 획득 연출: 플래시 텍스트
        const flashText = this.add.text(this.scale.width / 2, this.scale.height / 2 - 60,
          `+${result.skorAwarded} SKOR 획득!`, {
          fontSize: '24px',
          color: '#ffcc00',
          fontStyle: 'bold',
          stroke: '#000',
          strokeThickness: 5,
        }).setOrigin(0.5).setAlpha(0);

        this.tweens.add({
          targets: flashText,
          alpha: { from: 1, to: 0 },
          y: flashText.y - 40,
          duration: 1500,
          ease: 'Cubic.easeOut',
          onComplete: () => flashText.destroy(),
        });
      } else if (result.alreadyClaimed) {
        if (this.prevSeasonReward) {
          this.prevSeasonReward = { ...this.prevSeasonReward, alreadyClaimed: true };
        }
        this.updateRewardUI();
      } else {
        // 보상 없음 (순위 밖 등)
        this.updateRewardUI();
      }
    } catch {
      // 실패 시 버튼 복구
      btnText.setText(`🏆  보상받기  +${this.prevSeasonReward?.skorAwarded ?? 0} SKOR`);
      btnBg.setInteractive({ useHandCursor: true });
    }
  }

  private createBackButton(cx: number, y: number) {
    const button = this.add.rectangle(cx, y, 150, 40, 0xffffff, 1);
    button.setStrokeStyle(3, 0x000000);

    const text = this.add.text(cx, y, '← 뒤로가기', {
      fontSize: '18px',
      color: '#000',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    button.setInteractive({ useHandCursor: true });

    const elements = [button, text];
    elements.forEach(element => {
      element.on('pointerover', () => {
        button.setFillStyle(0xffff99);
      });

      element.on('pointerout', () => {
        button.setFillStyle(0xffffff);
      });

      element.on('pointerdown', () => {
        this.scene.start('ModeSelectScene');
      });
    });
  }
}

