        alpha: { from: 1, to: 0 },
        y: flashText.y - 40,
        duration: 1500,
        ease: 'Cubic.easeOut',
        onComplete: () => flashText.destroy(),
      });
    } else {
      if (this.prevSeasonReward && result.alreadyClaimed) {
        this.prevSeasonReward = { ...this.prevSeasonReward, alreadyClaimed: true };
      }
      this.updateRewardUI();
    }
  } catch {
    // 실패 시 원래 상태로 복구
    this.updateRewardUI();
  }
}

