      const rewardDiffs: Difficulty[] = [DifficultyEnum.NORMAL, DifficultyEnum.HARD, DifficultyEnum.EXTREME, DifficultyEnum.PHYSICAL];
      if (rewardDiffs.includes(this.selectedDifficulty) && response.yearMonth) {
