 * 1등: 30,000 / 2등: 20,000 / 3등: 10,000
 * 상위 10%: 5,000 / 상위 50%: 3,000 / 나머지 참여자: 1,000
 */
function getReward(rank: number, totalPlayers: number): number {
  if (rank === 1) return 30000;
  if (rank === 2) return 20000;
  if (rank === 3) return 10000;
  const percentile = rank / totalPlayers;
  if (percentile <= 0.10) return 5000;
  if (percentile <= 0.50) return 3000;
  return 1000;
}

/** 현재 달 'YYYY-MM' 반환 (UTC 기준) */
function getCurrentYearMonth(): string {
  const now = new Date();
  const y = now.getUTCFullYear();
  const m = String(now.getUTCMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

/** 직전 달 'YYYY-MM' 반환 */
function getPrevYearMonth(current: string): string {
  const [y, m] = current.split('-').map(Number) as [number, number];
  const prev = new Date(Date.UTC(y, m - 2, 1));
  return `${prev.getUTCFullYear()}-${String(prev.getUTCMonth() + 1).padStart(2, '0')}`;
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { difficulty } = await req.json();

    const validDifficulties = ['normal', 'hard', 'extreme', 'physical'];
    if (!validDifficulties.includes(difficulty)) {
      return new Response(
        JSON.stringify({ error: 'Invalid difficulty' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // JWT 인증
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const supabaseUser = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
      { global: { headers: { Authorization: authHeader } } }
    );
    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    if (authError || !user) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    const currentYearMonth = getCurrentYearMonth();
    const prevYearMonth = getPrevYearMonth(currentYearMonth);

    // 보상 수령 기간 검증: 직전 달 기록만 수령 가능
    // (새 달이 되면 이전 이전 달은 자동으로 접근 불가)
    // 클라이언트가 임의의 year_month를 body에 넣어 오래된 달 청구 시도를 차단하기 위해
    // 서버에서 항상 현재 기준 직전 달로 고정

    // 이미 수령했는지 확인
    const { data: existingReward } = await supabaseAdmin
      .from('season_reward_history')
      .select('skor_awarded, rank')
      .eq('year_month', prevYearMonth)
      .eq('user_id', user.id)
      .eq('difficulty', typedDifficulty)
      .single();

    if (existingReward) {
      return new Response(
        JSON.stringify({
          success: true,
          alreadyClaimed: true,
          rank: existingReward.rank,
          skorAwarded: existingReward.skor_awarded,
        }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // 직전 달 리더보드에서 유저 순위 계산
    const { data: allScores } = await supabaseAdmin
      .from('leaderboard')
      .select('user_id, score')
      .eq('difficulty', typedDifficulty)
      .eq('year_month', prevYearMonth)
      .order('score', { ascending: false });

    if (!allScores || allScores.length === 0) {
      return new Response(
        JSON.stringify({ success: true, alreadyClaimed: false, rank: null, skorAwarded: 0 }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const rankIndex = allScores.findIndex(r => r.user_id === user.id);
    if (rankIndex === -1) {
      // 해당 달에 기록 없음
      return new Response(
        JSON.stringify({ success: true, alreadyClaimed: false, rank: null, skorAwarded: 0 }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const rank = rankIndex + 1;
    const totalPlayers = allScores.length;
    const reward = getReward(rank, totalPlayers);

    // 보상 이력 INSERT (UNIQUE 제약으로 race condition 방지)
    const { error: historyError } = await supabaseAdmin
      .from('season_reward_history')
      .insert({
        year_month: prevYearMonth,
        user_id: user.id,
        difficulty: typedDifficulty,
        rank,
        skor_awarded: reward,
      });

    if (historyError) {
      if (historyError.code === '23505') {
        // 동시 요청으로 이미 INSERT됨 → alreadyClaimed 처리
        return new Response(
          JSON.stringify({ success: true, alreadyClaimed: true, rank, skorAwarded: reward }),
          { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }
      console.error('History insert error:', historyError);
      return new Response(
        JSON.stringify({ error: 'Failed to record reward' }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // user_skor 잔액 증가
    const { data: existingSkor } = await supabaseAdmin
      .from('user_skor')
      .select('balance, weekly_earned, week_start')
      .eq('user_id', user.id)
      .single();

    const newBalance = Math.floor((existingSkor?.balance ?? 0) + reward);

    // 주간 집계 처리
    const now = new Date();
    const dayOfWeek = now.getUTCDay();
    const daysFromMonday = (dayOfWeek + 6) % 7;
    const weekStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - daysFromMonday));
    const weekStartStr = weekStart.toISOString().slice(0, 10);
    const isSameWeek = existingSkor?.week_start === weekStartStr;
    const newWeeklyEarned = isSameWeek
      ? Math.floor((existingSkor?.weekly_earned ?? 0) + reward)
      : Math.floor(reward);

    await supabaseAdmin
      .from('user_skor')
      .upsert({
        user_id: user.id,
        balance: newBalance,
        weekly_earned: newWeeklyEarned,
        week_start: weekStartStr,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'user_id' });

    return new Response(
      JSON.stringify({
        success: true,
        alreadyClaimed: false,
        rank,
        skorAwarded: reward,
        newBalance,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('Unexpected error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

