import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

/** 현재 달 'YYYY-MM' 반환 (UTC 기준) */
function getCurrentYearMonth(): string {
  const now = new Date();
  const y = now.getUTCFullYear();
  const m = String(now.getUTCMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

/** 직전 달 'YYYY-MM' 반환 */
function getPrevYearMonth(current: string): string {
  const [y, m] = current.split('-').map(Number) as [number, number];
  const prev = new Date(Date.UTC(y, m - 2, 1));
  return `${prev.getUTCFullYear()}-${String(prev.getUTCMonth() + 1).padStart(2, '0')}`;
}

/** 시즌 번호: 2026-01 = 1, 2026-02 = 2, ... */
function calcSeason(yearMonth: string): number {
  const [y, m] = yearMonth.split('-').map(Number) as [number, number];
  return (y - 2026) * 12 + m;
}

/**
 * 시즌 보상 계산 (난이도 무관, 퍼센타일 기반)
 * 1등: 30,000 / 2등: 20,000 / 3등: 10,000
 * 상위 10%: 5,000 / 상위 50%: 3,000 / 나머지 참여자: 1,000
 */
function getReward(rank: number, totalPlayers: number): number {
  if (rank === 1) return 30000;
  if (rank === 2) return 20000;
  if (rank === 3) return 10000;
  const percentile = rank / totalPlayers;
  if (percentile <= 0.10) return 5000;
  if (percentile <= 0.50) return 3000;
  return 1000;
}

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

Deno.serve(async (req: Request) => {
  // CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { difficulty, limit: limitParam } = await req.json().catch(() => ({}));
    const limit = parseInt(limitParam ?? '100', 10);

    // 입력 검증
    const validDifficulties = ['easy', 'normal', 'hard', 'extreme', 'physical'];
    if (!difficulty || !validDifficulties.includes(difficulty)) {
      return new Response(
        JSON.stringify({ error: 'Invalid difficulty' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const safeLimit = Math.min(Math.max(1, limit), 100);

    // JWT에서 사용자 인증 (선택적 — 비로그인 시에도 랭킹 조회 가능)
    const authHeader = req.headers.get('Authorization');
    let currentUserId: string | null = null;

    if (authHeader) {
      const supabaseUser = createClient(
        Deno.env.get('SUPABASE_URL') ?? '',
        Deno.env.get('SUPABASE_ANON_KEY') ?? '',
        { global: { headers: { Authorization: authHeader } } }
      );
      const { data: { user } } = await supabaseUser.auth.getUser();
      currentUserId = user?.id ?? null;
    }

    // Service Role 클라이언트 (profiles JOIN을 위해)
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    const yearMonth = getCurrentYearMonth();
    const prevYearMonth = getPrevYearMonth(yearMonth);

    // 현재 시즌 리더보드 조회 (profiles와 JOIN하여 이니셜 포함)
    const { data: leaderboard, error: leaderboardError } = await supabaseAdmin
      .from('leaderboard')
      .select(`
        user_id,
        score,
        character_type,
        profiles!inner(initials)
      `)
      .eq('difficulty', difficulty)
      .eq('year_month', yearMonth)
      .order('score', { ascending: false })
      .limit(safeLimit);

    if (leaderboardError) {
      console.error('Leaderboard query error:', leaderboardError);
      return new Response(
        JSON.stringify({ error: 'Failed to fetch leaderboard' }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // 응답 형식 변환
    const entries = (leaderboard ?? []).map((entry, index) => ({
      userId: entry.user_id,
      userName: (entry.profiles as { initials: string | null }).initials ?? '???',
      score: entry.score,
      rank: index + 1,
      characterType: (entry as Record<string, unknown>).character_type ?? 'chibi',
    }));

    const totalEntries = entries.length;

    // 현재 유저의 이번 시즌 순위 조회
    let currentUserRank: { rank: number; score: number } | null = null;
    // 직전 시즌 보상 상태 (로그인 유저에게만 제공)
    let prevSeasonReward: {
      yearMonth: string;
      rank: number | null;
      skorAwarded: number;
      alreadyClaimed: boolean;
    } | null = null;

    if (currentUserId) {
      const { data: userEntry } = await supabaseAdmin
        .from('leaderboard')
        .select('score')
        .eq('user_id', currentUserId)
        .eq('difficulty', difficulty)
        .eq('year_month', yearMonth)
        .single();

      if (userEntry) {
        const { count: higherCount } = await supabaseAdmin
          .from('leaderboard')
          .select('*', { count: 'exact', head: true })
          .eq('difficulty', difficulty)
          .eq('year_month', yearMonth)
          .gt('score', userEntry.score);

        currentUserRank = {
          rank: (higherCount ?? 0) + 1,
          score: userEntry.score,
        };
      }

      // 직전 시즌 보상 상태 조회 (easy 제외)
      if (difficulty !== 'easy') {
        // 이미 수령했는지 확인
        const { data: claimed } = await supabaseAdmin
          .from('season_reward_history')
          .select('skor_awarded, rank')
          .eq('year_month', prevYearMonth)
          .eq('user_id', currentUserId)
          .eq('difficulty', difficulty)
          .single();

        if (claimed) {
          prevSeasonReward = {
            yearMonth: prevYearMonth,
            rank: claimed.rank,
            skorAwarded: claimed.skor_awarded,
            alreadyClaimed: true,
          };
        } else {
          // 직전 달 리더보드에서 순위 계산
          const { data: prevScores } = await supabaseAdmin
            .from('leaderboard')
            .select('user_id, score')
            .eq('difficulty', difficulty)
            .eq('year_month', prevYearMonth)
            .order('score', { ascending: false });

          if (prevScores && prevScores.length > 0) {
            const rankIdx = prevScores.findIndex(r => r.user_id === currentUserId);
            if (rankIdx !== -1) {
              const rank = rankIdx + 1;
              const skorAwarded = getReward(rank, prevScores.length);
              prevSeasonReward = {
                yearMonth: prevYearMonth,
                rank,
                skorAwarded,
                alreadyClaimed: false,
              };
            }
          }
        }
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        difficulty,
        yearMonth,
        season: calcSeason(yearMonth),
        leaderboard: entries,
        currentUserRank,
        totalEntries,
        prevSeasonReward,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('Unexpected error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

