1	import type Phaser from 'phaser';
2	import { Difficulty, Difficulty as DifficultyEnum } from '../types/GameMode';
3	import {
4	  getLeaderboard,
5	  claimSeasonReward,
6	  getCachedClaimAmount,
7	  type LeaderboardEntry,
8	  type PrevSeasonReward,
9	} from '../utils/leaderboard';
10	import BaseScene from './BaseScene';
11	
12	export default class LeaderboardScene extends BaseScene {
13	  private selectedDifficulty: Difficulty = DifficultyEnum.NORMAL;
14	  private leaderboardData: LeaderboardEntry[] = [];
15	  private leaderboardTexts: Phaser.GameObjects.Text[] = [];
16	  private loadingText?: Phaser.GameObjects.Text;
17	  private errorText?: Phaser.GameObjects.Text;
18	  private currentRequestId: number = 0;
19	  private difficultyButtons = new Map<Difficulty, Phaser.GameObjects.Rectangle>();
20	
21	  // 시즌 UI 요소
22	  private seasonText?: Phaser.GameObjects.Text;
23	  private rewardAreaObjects: Phaser.GameObjects.GameObject[] = [];
24	  private prevSeasonReward: PrevSeasonReward | null = null;
25	
26	  // 보상수령 버튼 (create에서 1회 생성, updateRewardUI에서 상태 변경)
27	  private rewardBtnBg?: Phaser.GameObjects.Rectangle;
28	  private rewardBtnLabel?: Phaser.GameObjects.Text;
29	
30	  constructor() {
31	    super('LeaderboardScene');
32	  }
33	
34	  init() {
35	    const last = localStorage.getItem('lastPlayedDifficulty') as Difficulty | null;
36	    if (last) {
37	      this.selectedDifficulty = last;
38	    }
39	  }
40	
41	  preload() {
42	    // 배경 이미지 로드 (캐시 확인으로 중복 로딩 방지)
43	    if (!this.textures.exists('background2')) {
44	      this.load.image('background2', 'assets/backgrounds/background2.webp');
45	    }
46	  }
47	
48	  create() {
49	    super.create();
50	
51	    const W = this.scale.width;
52	    const H = this.scale.height;
53	    const cx = W / 2;
54	    const yOff = (H - 600) / 2;
55	
56	    // 배경 이미지 추가
57	    const background = this.add.image(cx, H / 2, 'background2');
58	    background.setDisplaySize(W, H);
59	
60	    // 타이틀
61	    this.add.text(cx, 40 + yOff, '🏆 랭킹보드 🏆', {
62	      fontSize: '28px',
63	      color: '#fff',
64	      fontStyle: 'bold',
65	      stroke: '#000',
66	      strokeThickness: 5,
67	      padding: { top: 6 },
68	    }).setOrigin(0.5);
69	
70	    // 시즌 월 표시 (데이터 로드 후 갱신)
71	    this.seasonText = this.add.text(cx, 70 + yOff, '', {
72	      fontSize: '13px',
73	      color: '#aaddff',
74	      stroke: '#000',
75	      strokeThickness: 3,
76	    }).setOrigin(0.5);
77	
78	    // 난이도 선택 버튼들
79	    this.createDifficultyButtons(cx, yOff);
80	
81	    // 랭킹 표시 영역 (초기 로딩)
82	    this.loadingText = this.add.text(cx, H / 2, '로딩 중...', {
83	      fontSize: '20px',
84	      color: '#fff',
85	      stroke: '#000',
86	      strokeThickness: 3
87	    }).setOrigin(0.5);
88	
89	    // 보상수령 버튼 (하단 왼쪽, 뒤로가기와 나란히)
90	    const rbY = H - 40;
91	    this.rewardBtnBg = this.add.rectangle(cx - 80, rbY, 150, 40, 0x555555, 1);
92	    this.rewardBtnBg.setStrokeStyle(3, 0x333333);
93	    this.rewardBtnLabel = this.add.text(cx - 80, rbY, '보상수령', {
94	      fontSize: '18px',
95	      color: '#999999',
96	      fontStyle: 'bold',
97	      stroke: '#000',
98	      strokeThickness: 4,
99	    }).setOrigin(0.5);
100	
101	    // 뒤로가기 버튼 (하단 오른쪽)
102	    this.createBackButton(cx + 80, H - 40);
103	
104	    // 초기 데이터 로드
105	    this.loadLeaderboard();
106	  }
107	
108	  private createDifficultyButtons(cx: number, yOff: number) {
109	    this.difficultyButtons.forEach(btn => btn.destroy());
110	    this.difficultyButtons.clear();
111	
112	    const difficulties: Difficulty[] = [
113	      DifficultyEnum.NORMAL,
114	      DifficultyEnum.HARD,
115	      DifficultyEnum.EXTREME,
116	      DifficultyEnum.PHYSICAL
117	    ];
118	
119	    const buttonWidth = 70;
120	    const spacing = 85;
121	    const startX = cx - (spacing * 1.5);
122	    const y = 108 + yOff;
123	
124	    difficulties.forEach((difficulty, index) => {
125	      const x = startX + (index * spacing);
126	      const isSelected = difficulty === this.selectedDifficulty;
127	
128	      const button = this.add.rectangle(
129	        x,
130	        y,
131	        buttonWidth,
132	        35,
133	        isSelected ? 0xffff99 : 0xffffff,
134	        1
135	      );
136	      button.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
137	
138	      this.add.text(x, y, difficulty, {
139	        fontSize: '12px',
140	        color: '#000',
141	        fontStyle: 'bold'
142	      }).setOrigin(0.5);
143	
144	      this.difficultyButtons.set(difficulty, button);
145	      button.setInteractive({ useHandCursor: true });
146	
147	      button.on('pointerover', () => {
148	        if (difficulty !== this.selectedDifficulty) {
149	          button.setFillStyle(0xffffcc);
150	        }
151	      });
152	
153	      button.on('pointerout', () => {
154	        if (difficulty !== this.selectedDifficulty) {
155	          button.setFillStyle(0xffffff);
156	        }
157	      });
158	
159	      button.on('pointerdown', () => {
160	        this.selectDifficulty(difficulty);
161	      });
162	    });
163	  }
164	
165	  private selectDifficulty(difficulty: Difficulty) {
166	    // 같은 난이도면 무시
167	    if (this.selectedDifficulty === difficulty) {
168	      return;
169	    }
170	
171	    this.selectedDifficulty = difficulty;
172	
173	    // 모든 버튼 스타일 재설정
174	    this.difficultyButtons.forEach((btn, diff) => {
175	      const isSelected = diff === difficulty;
176	      btn.setFillStyle(isSelected ? 0xffff99 : 0xffffff);
177	      btn.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
178	    });
179	
180	    // 새로운 난이도 데이터 로드
181	    this.loadLeaderboard();
182	  }
183	
184	  private async loadLeaderboard() {
185	    // 요청 ID 증가 (새로운 요청 시작)
186	    this.currentRequestId++;
187	    const requestId = this.currentRequestId;
188	
189	    // 기존 랭킹 텍스트 + 보상 UI 제거
190	    this.leaderboardTexts.forEach(text => text.destroy());
191	    this.leaderboardTexts = [];
192	    this.rewardAreaObjects.forEach(o => o.destroy());
193	    this.rewardAreaObjects = [];
194	    this.prevSeasonReward = null;
195	
196	    if (this.errorText) {
197	      this.errorText.destroy();
198	      this.errorText = undefined;
199	    }
200	
201	    // 로딩 표시
202	    if (!this.loadingText) {
203	      this.loadingText = this.add.text(this.scale.width / 2, this.scale.height / 2, '로딩 중...', {
204	        fontSize: '20px',
205	        color: '#fff',
206	        stroke: '#000',
207	        strokeThickness: 3
208	      }).setOrigin(0.5);
209	    } else {
210	      this.loadingText.setVisible(true);
211	    }
212	
213	    try {
214	      const response = await getLeaderboard(this.selectedDifficulty, 10);
215	
216	      // 응답이 도착했을 때 최신 요청인지 확인
217	      if (requestId !== this.currentRequestId) {
218	        // 이미 새로운 요청이 시작됨 - 이 응답은 무시
219	        return;
220	      }
221	
222	      this.leaderboardData = response.leaderboard;
223	
224	      // 시즌 텍스트 갱신
225	      if (this.seasonText && response.yearMonth) {
226	        const [y, m] = response.yearMonth.split('-');
227	        const daysLeft = this.calcDaysUntilMonthEnd();
228	        this.seasonText.setText(`${y}년 ${parseInt(m)}월 시즌  |  시즌 종료까지 D-${daysLeft}`);
229	      }
230	
231	      // 직전 달 보상 상태 결정 (localStorage 캐시 우선)
232	      const rewardDiffs: Difficulty[] = [DifficultyEnum.NORMAL, DifficultyEnum.HARD, DifficultyEnum.EXTREME, DifficultyEnum.PHYSICAL];
233	      if (rewardDiffs.includes(this.selectedDifficulty) && response.yearMonth) {
234	        const [y, m] = response.yearMonth.split('-').map(Number) as [number, number];
235	        const prevDate = new Date(y, m - 2, 1);
236	        const prevYM = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
237	        const cached = getCachedClaimAmount(prevYM, this.selectedDifficulty);
238	        if (cached !== null) {
239	          // localStorage 캐시 히트 → 서버 응답의 prevSeasonReward 무시하고 캐시 사용
240	          this.prevSeasonReward = {
241	            yearMonth: prevYM,
242	            rank: response.prevSeasonReward?.rank ?? null,
243	            skorAwarded: cached,
244	            alreadyClaimed: true,
245	          };
246	        } else {
247	          this.prevSeasonReward = response.prevSeasonReward;
248	        }
249	      } else {
250	        this.prevSeasonReward = null;
251	      }
252	
253	      if (this.loadingText) {
254	        this.loadingText.setVisible(false);
255	      }
256	
257	      this.displayLeaderboard();
258	      this.updateRewardUI();
259	    } catch (error) {
260	      // 에러가 발생했을 때도 최신 요청인지 확인
261	      if (requestId !== this.currentRequestId) {
262	        // 이미 새로운 요청이 시작됨 - 이 에러는 무시
263	        return;
264	      }
265	
266	      console.error('Failed to load leaderboard:', error);
267	
268	      if (this.loadingText) {
269	        this.loadingText.setVisible(false);
270	      }
271	
272	      this.errorText = this.add.text(this.scale.width / 2, this.scale.height / 2, '랭킹을 불러올 수 없습니다\n\n나중에 다시 시도해주세요', {
273	        fontSize: '16px',
274	        color: '#ff6666',
275	        stroke: '#000',
276	        strokeThickness: 3,
277	        align: 'center'
278	      }).setOrigin(0.5);
279	    }
280	  }
281	
282	  private displayLeaderboard() {
283	    const yOff = (this.scale.height - 600) / 2;
284	    const cx = this.scale.width / 2;
285	    const startY = 163 + yOff;
286	    const lineHeight = 35;
287	
288	    // 헤더
289	    const headerText = this.add.text(cx, startY, '순위    이름      점수', {
290	      fontSize: '16px',
291	      color: '#ffff00',
292	      fontStyle: 'bold',
293	      stroke: '#000',
294	      strokeThickness: 4
295	    }).setOrigin(0.5);
296	    this.leaderboardTexts.push(headerText);
297	
298	    // 랭킹 데이터 표시
299	    if (this.leaderboardData.length === 0) {
300	      const noDataText = this.add.text(cx, startY + 50, '아직 랭킹이 없습니다\n\n첫 번째 플레이어가 되어보세요!', {
301	        fontSize: '18px',
302	        color: '#ccc',
303	        stroke: '#000',
304	        strokeThickness: 3,
305	        align: 'center'
306	      }).setOrigin(0.5);
307	      this.leaderboardTexts.push(noDataText);
308	      return;
309	    }
310	
311	    this.leaderboardData.forEach((entry, index) => {
312	      const y = startY + 30 + (index * lineHeight);
313	
314	      // 순위별 색상
315	      let color = '#ffffff';
316	      if (entry.rank === 1) color = '#FFD700'; // 금색
317	      else if (entry.rank === 2) color = '#C0C0C0'; // 은색
318	      else if (entry.rank === 3) color = '#CD7F32'; // 동색
319	
320	
321	      const rankText = `${entry.rank}`.padEnd(8, ' ');
322	      const nameText = entry.userName.padEnd(8, ' ');
323	      const scoreText = entry.score.toString().padStart(6, ' ');
324	
325	      const text = this.add.text(
326	        cx,
327	        y,
328	        `${rankText}${nameText}${scoreText}`,
329	        {
330	          fontSize: '16px',
331	          color: color,
332	          fontFamily: 'monospace',
333	          stroke: '#000',
334	          strokeThickness: 3
335	        }
336	      ).setOrigin(0.5);
337	
338	      this.leaderboardTexts.push(text);
339	    });
340	  }
341	
342	  /** 이번 달 말일까지 남은 일수 */
343	  private calcDaysUntilMonthEnd(): number {
344	    const now = new Date();
345	    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
346	    const diff = lastDay.getTime() - now.getTime();
347	    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
348	  }
349	
350	  /** 보상수령 버튼 상태 갱신 */
351	  private updateRewardUI() {
352	    if (!this.rewardBtnBg || !this.rewardBtnLabel) return;
353	
354	    const btn = this.rewardBtnBg;
355	    const label = this.rewardBtnLabel;
356	    const reward = this.prevSeasonReward;
357	
358	    btn.removeAllListeners();
359	    btn.disableInteractive();
360	
361	    if (!reward || reward.rank === null || reward.skorAwarded === 0) {
362	      // 비활성: 기록 없음 또는 100위 밖
363	      btn.setFillStyle(0x555555).setStrokeStyle(3, 0x333333);
